import icontract
from typing import List


@icontract.require(lambda a, e: any(a[i] == e for i in range(len(a))))
@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda a, result: result < len(a))
@icontract.ensure(lambda a, e, result: a[result] == e)
@icontract.ensure(lambda a, e, result: all(a[k] != e for k in range(result)))
def LinearSearch(a: List[int], e: int) -> int:
    i = 0
    while i < len(a) and a[i] != e:
        i += 1
    return i
